  P.COURSES.VT.codes = 'ASME V Art. 9 · ISO 17637 · ISO 5817 · ISO 6520 · ASME VIII UW-35 · ASME B31.3 · ASME IX · ISO 9606, 15614 · AWS A2.4, ISO 2553';
